function parseAttendees(text){return text.split(/\r?\n/).filter(x=>x.trim()).map((raw,i)=>{let line=raw.trim().replace(/^\s*\d+[.)]\s+/,'');const tag=line.match(/^\[([^\]]+)\]\s*/);const alliance=tag?tag[1]:'';if(tag)line=line.slice(tag[0].length);const idOnly=line.match(/^\d{5,}$/);if(idOnly)return{raw,name:'',playerId:idOnly[0],alliance,line:i+1};const suffix=line.match(/^(.*?)(?:,\s*|\s+ID[:：]?\s*)(\d{5,})\s*$/i);return{raw,name:suffix?suffix[1].trim():line,playerId:suffix?suffix[2]:'',alliance,line:i+1}})}
